create table if not exists alerts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),alert_type text not null,severity text not null default 'medium',entity_type text,entity_id uuid,description text not null,status text default 'open',resolution_notes text,created_at timestamptz default now(),resolved_at timestamptz);
create table if not exists forecast_snapshots(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),product_id uuid references products(id),period_start date not null,period_end date not null,forecast_qty numeric(18,3) not null,method text not null,created_at timestamptz default now());
